import React, { useEffect, useState, useRef } from "react";
import axios from "axios";
import {
  MapContainer,
  TileLayer,
  Polyline,
  Marker,
  Tooltip
} from "react-leaflet";
import "leaflet/dist/leaflet.css";

import {
  Line
} from "react-chartjs-2";

import {
  Chart as ChartJS,
  LineElement,
  CategoryScale,
  LinearScale,
  PointElement
} from "chart.js";

ChartJS.register(LineElement, CategoryScale, LinearScale, PointElement);

function App() {
  const [data, setData] = useState([]);
  const [path, setPath] = useState([]);
  const [index, setIndex] = useState(0);
  const [playing, setPlaying] = useState(false);

  const mapRef = useRef();

  // ⏱ Time filter
  const [startTime, setStartTime] = useState("");
  const [endTime, setEndTime] = useState("");

  // 🚀 FETCH DATA
  const fetchData = async () => {
    try {
      const res = await axios.get("http://localhost:3000/path", {
        params: {
          start: startTime,
          end: endTime
        }
      });

      const d = res.data;

      setData(d);

      // Convert to path
      const coords = d.map(p => ({
        lat: p.location.coordinates[1],
        lng: p.location.coordinates[0],
        alt: p.alt,
        voltage: p.voltage
      }));

      setPath(coords);

      // 🔥 AUTO ZOOM TO PATH
      if (coords.length > 0 && mapRef.current) {
        const bounds = coords.map(c => [c.lat, c.lng]);
        mapRef.current.fitBounds(bounds);
      }

    } catch (err) {
      console.error(err);
    }
  };

  // ▶ PLAY ANIMATION
  useEffect(() => {
    if (!playing) return;

    const interval = setInterval(() => {
      setIndex(prev => {
        if (prev >= path.length - 1) {
          clearInterval(interval);
          return prev;
        }
        return prev + 1;
      });
    }, 100); // speed

    return () => clearInterval(interval);
  }, [playing, path]);

  // 📍 FOLLOW DRONE
  useEffect(() => {
    if (path[index] && mapRef.current) {
      mapRef.current.setView([path[index].lat, path[index].lng], 18);
    }
  }, [index]);

  // 📊 GRAPH DATA
const chartOptions = {
  responsive: true,
  plugins: {
    legend: {
      labels: {
        color: "white"
      }
    }
  },
  scales: {
    x: {
      ticks: { color: "white" }
    },
    y: {
      ticks: { color: "white" }
    }
  }
};

  return (
    <div style={{ background: "black", color: "white", height: "100vh" }}>
      <h2>🚁 Drone Timeline (Playback Mode)</h2>

      {/* ⏱ TIME FILTER */}
      <div>
        Start:
        <input
          type="datetime-local"
          value={startTime}
          onChange={e => setStartTime(e.target.value)}
        />

        End:
        <input
          type="datetime-local"
          value={endTime}
          onChange={e => setEndTime(e.target.value)}
        />

        <button onClick={fetchData}>Apply</button>
      </div>

      {/* ▶ CONTROLS */}
      <div>
        <button onClick={() => setPlaying(true)}>▶ Play</button>
        <button onClick={() => setPlaying(false)}>⏸ Pause</button>
      </div>

      {/* 🗺 MAP */}
      <MapContainer
        center={[12.97, 77.59]}
        zoom={13}
        style={{ height: "60vh" }}
        whenCreated={(map) => (mapRef.current = map)}
      >
        <TileLayer
          url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        />

        {/* 🔵 PATH DRAW */}
        <Polyline
          positions={path.slice(0, index).map(p => [p.lat, p.lng])}
          color="cyan"
        />

        {/* 📍 DRONE MARKER */}
        {path[index] && (
          <Marker position={[path[index].lat, path[index].lng]}>
            <Tooltip>
              Alt: {path[index].alt} m <br />
              Battery: {path[index].voltage} V
            </Tooltip>
          </Marker>
        )}
      </MapContainer>

      {/* 📊 GRAPH */}
      <div style={{ height: "30vh", background: "#111" }}>
        <Line data={chartData} />
      </div>
    </div>
  );
}

export default App;
